const LOCATION_REPAIR_CODES=new Set(["LOCATION_REPAIR_REQUIRED","LOCATION_PROPOSAL_REQUIRED","LOCATION_EFFECT_CONFLICT","LOCATION_SET_REQUIRES_NODE","LOCATION_SET_CONFLICT","UNDECLARED_LOCATION_TRANSITION"]);
