/* =========================
   上下文摘要
========================= */
async function maybeAutoSummarize(){
  const lastIndex=state.context.lastSummarizedMessageId?state.messages.findIndex(m=>m.id===state.context.lastSummarizedMessageId):-1;
  const unsummarized=state.messages.slice(lastIndex+1);if(unsummarized.length<state.context.summaryThreshold||activeAbortController||state.runtime.phase!=="awaiting_player_action")return;
  try{await summarizeContext(false)}catch(error){addLog("summary",`自动摘要失败：${error.message}`)}
}
async function summarizeContext(manual=true){
  if(activeAbortController||state.runtime.summaryInProgress)throw new Error("当前有请求正在进行");
  const lastIndex=state.context.lastSummarizedMessageId?state.messages.findIndex(m=>m.id===state.context.lastSummarizedMessageId):-1;
  const cutoff=Math.max(lastIndex+1,state.messages.length-state.context.recentMessageLimit);const older=state.messages.slice(lastIndex+1,cutoff);
  if(!older.length)throw new Error("没有需要整理的旧消息");state.runtime.summaryInProgress=true;renderChatComposer();const requestId=uid("summary");
  const prompt=`总结以下 TRPG 历史。只能总结已发生事件、NPC 态度、未解决问题、伏笔和玩家已知信息。不得推断或修改 HP、SAN、物品、状态、骰点、节点、线索和标记。只返回纯文本摘要。\n现有摘要：${state.context.rollingSummary}\n消息：${JSON.stringify(older.map(m=>({role:m.role,content:m.content})))}`;
  try{
    const raw=await callChatCompletion([{role:"system",content:"你是上下文摘要器，不修改任何结构化状态。"},{role:"user",content:prompt}],{timeoutMs:45000,jsonMode:false});state.context.rollingSummary=asString(raw,12000);state.context.lastSummarizedMessageId=older.at(-1)?.id||null;bumpRevision();addLog("summary",manual?"手动整理上下文":"自动整理上下文");toast("上下文整理完成","ok");renderAll();
  }finally{state.runtime.summaryInProgress=false;renderChatComposer()}
}

